      "id": "paid_search_advertising",
      "name": "Paid Search Advertising (Google Ads, Bing)",
      "category": "performance_marketing",
      "description": "Managing paid search campaigns across Google Ads (Search, Shopping, Display, YouTube, UAC) and Bing Ads. Includes keyword strategy, bid management, ad copywriting, quality score optimization, campaign structure, and performance analysis.",
      "proficiency_levels": {
        "beginner": "Can set up basic search campaigns with keyword research, ad copy, and standard bidding. Understands match types, quality score components, and basic campaign structure.",
        "intermediate": "Manages complex campaign structures across Search, Display, YouTube, and/or UAC with significant budgets. Optimizes bids, keywords, and ad copy based on conversion data. Implements negative keywords, audience layering, and automated bidding strategies. Manages Google Ads for app install or lead generation at scale.",
        "advanced": "Manages multi-million dollar Google Ads portfolios with full P&L accountability. Builds sophisticated bidding strategies using scripts, rules, and third-party tools. Optimizes across the full Google ecosystem (Search, Shopping, Display, YouTube, UAC, Performance Max). Deep understanding of auction dynamics, attribution, and incrementality."
      }
